test('adjustStock cannot take stock below the reserved units', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 7 }]);
  await assert.rejects(svc.adjustStock('widget', -4, 'count'), error => {
    assert.ok(error instanceof InsufficientStockError);
    assert.equal(error.requested, 4);
    assert.equal(error.available, 3);
    return true;
  });
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 7, sold: 0 });
  assert.equal((await svc.adjustStock('widget', -3, 'count')).stock, 7);
});

test('adjustStock is safe alongside concurrent reserve, commit and release', async () => {
  const svc = await service({ widget: 100 });
  const ids = Array.from({ length: 20 }, (_, i) => `o${i}`);
  const work = [];
  ids.forEach((id, i) => {
    work.push(svc.reserve(id, [{ sku: 'widget', qty: 2 }]).then(() => (i % 2 ? svc.commit(id) : svc.release(id))));
  });
  // Removals that fit even in the worst case, plus additions.
  for (let i = 0; i < 10; i++) {
    work.push(svc.adjustStock('widget', -1, 'count'));
    work.push(svc.adjustStock('widget', 3, 'count'));
  }
  await Promise.all(work);
  // 100 + 10*(3-1) = 120 on hand before sales; 10 orders of 2 were sold.
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 100, reserved: 0, sold: 20 });
});

test('concurrent removals never take stock below reserved', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
  const results = await Promise.allSettled(Array.from({ length: 10 }, () => svc.adjustStock('widget', -1, 'count')));
  assert.equal(results.filter(r => r.status === 'fulfilled').length, 6);
  for (const r of results.filter(r => r.status === 'rejected')) {
    assert.ok(r.reason instanceof InsufficientStockError);
  }
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 4, reserved: 4, sold: 0 });
});
